def button(text='Start a Project',href='/contact.html',secondary=False):
    return f'<a class="button {"secondary" if secondary else ""}" href="{href}">{text}<span aria-hidden="true">↗</span></a>'
def section_head(kicker,title,desc=''):
    return f'<div class="section-head"><p class="eyebrow">{kicker}</p><h2>{title}</h2>'+ (f'<p class="lede">{desc}</p>' if desc else '')+'</div>'
def page_hero(kicker,title,desc):
    return f'<section class="page-hero"><div class="wrap"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lede">{desc}</p></div></section>'
def cta():
    return '<section class="wrap"><div class="cta"><div><p class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</p><h2>Let’s build something<br>great together.</h2><p>Bring your idea. We’ll help you find the next step.</p></div>'+button()+'</div></section>'
def asset_fingerprints(html):
    def version(match):
        file = D / match.group(2).lstrip('/')
        digest = hashlib.sha256(file.read_bytes()).hexdigest()[:12]
        return match.group(1) + match.group(2) + '?v=' + digest + match.group(3)
    return re.sub(r'((?:src|href)=")(/assets/[^"?]+)(")', version, html)

