    if kind=='business': inner='<div class="mini-nav">NORTHLINE <span>Spaces with purpose.</span></div><div class="mini-business"><p>THOUGHTFUL SPACES. LASTING IMPRESSIONS.</p><b>Room for<br>what’s next.</b><span class="mini-pill">Discover our approach ↗</span><div class="arch"><i></i></div></div><div class="mini-bottom">Architecture / Interiors / New perspectives</div>'
    elif kind=='store': inner='<div class="mini-nav">FORMA <span>Objects for everyday living</span></div><div class="mini-store"><div><p>LESS, BUT BETTER.</p><b>Considered<br>essentials.</b><span class="mini-pill">Explore the collection ↗</span></div><div class="vase"></div><div class="vase small"></div></div><div class="mini-bottom">Made to belong. Designed to last.</div>'
    else: inner='<div class="mini-nav">orbit / overview <span>Workspace ⌕</span></div><div class="mini-dashboard"><div class="mini-sidebar">◈<br>▦<br>☷<br>◷</div><div class="mini-data"><b>Your day, at a glance.</b><div class="stat-row"><span>Open tasks<strong>18</strong></span><span>In progress<strong>07</strong></span><span>Completed<strong>24</strong></span></div><div class="chart">'+''.join(f'<i style="height:{h}%"></i>' for h in [24,40,30,60,47,72,63,90,79,97])+'</div><div class="table-lines"><span>Website refresh <em>In progress</em></span><span>Content review <em>Ready</em></span></div></div></div>'
    return f'<div class="mock mock-{kind}" aria-label="Illustrative {kind} interface preview"><div class="window-bar"><i></i><i></i><i></i><span>CONCEPT EXPLORATION</span></div>{inner}</div>'
